    35  type BaseValidateCodeFormProps = WithToggleVisibilityViewProps &
    36      ValidateCodeFormProps & {
    37          /** Specifies autocomplete hints for the system, so it can provide autofill */
    38          autoComplete: 'sms-otp' | 'one-time-code';
    39      };
    40
    41  type BaseValidateCodeFormRef = {
    42      clearSignInData: () => void;
    43  };
    44
    45  type ValidateCodeFormVariant = 'validateCode' | 'twoFactorAuthCode' | 'recoveryCode';
    46
    47  type FormError = Partial<Record<ValidateCodeFormVariant, TranslationPaths>>;
