    49  function BaseValidateCodeForm({autoComplete, isUsingRecoveryCode, setIsUsingRecoveryCode, isVisible}: BaseValidateCodeFormProps, forwardedRef: ForwardedRef<BaseValidateCodeFormRef>) {
    50      const [account] = useOnyx(ONYXKEYS.ACCOUNT);
    51      const [credentials] = useOnyx(ONYXKEYS.CREDENTIALS);
    52      const [session] = useOnyx(ONYXKEYS.SESSION);
    53      const styles = useThemeStyles();
    54      const StyleUtils = useStyleUtils();
    55      const {translate} = useLocalize();
    56      const isFocused = useIsFocused();
    57      const {isOffline} = useNetwork();
    58      const [formError, setFormError] = useState<FormError>({});
    59      const [validateCode, setValidateCode] = useState(credentials?.validateCode ?? '');
    60      const [twoFactorAuthCode, setTwoFactorAuthCode] = useState('');
    61      const [timeRemaining, setTimeRemaining] = useState(CONST.REQUEST_CODE_DELAY as number);
    62      const [recoveryCode, setRecoveryCode] = useState('');
    63      const [needToClearError, setNeedToClearError] = useState<boolean>(!!account?.errors);
    64
    65      const prevRequiresTwoFactorAuth = usePrevious(account?.requiresTwoFactorAuth);
    66      const prevValidateCode = usePrevious(credentials?.validateCode);
    67
    68      const inputValidateCodeRef = useRef<MagicCodeInputHandle>();
    69      const input2FARef = useRef<MagicCodeInputHandle>();
    70      const timerRef = useRef<NodeJS.Timeout>();
    71
    72      const hasError = !!account && !isEmptyObject(account?.errors) && !needToClearError;
    73      const isLoadingResendValidationForm = account?.loadingForm === CONST.FORMS.RESEND_VALIDATE_CODE_FORM;
    74      const shouldDisableResendValidateCode = isOffline ?? account?.isLoading;
    75      const isValidateCodeFormSubmitting = AccountUtils.isValidateCodeFormSubmitting(account);
    76
    77      useEffect(() => {
    78          if (!(inputValidateCodeRef.current && hasError && (session?.autoAuthState === CONST.AUTO_AUTH_STATE.FAILED || account?.isLoading))) {
    79              return;
    80          }
    81          inputValidateCodeRef.current.blur();
    82      }, [account?.isLoading, session?.autoAuthState, hasError]);
    83
    84      useEffect(() => {
    85          if (!inputValidateCodeRef.current || !canFocusInputOnScreenFocus() || !isVisible || !isFocused) {
    86              return;
    87          }
    88          setTimeRemaining(CONST.REQUEST_CODE_DELAY);
    89          inputValidateCodeRef.current.focus();
    90      }, [isVisible, isFocused]);
    91
    92      useEffect(() => {
    93          if (!!prevValidateCode || !credentials?.validateCode) {
    94              return;
    95          }
    96          setValidateCode(credentials.validateCode);
    97      }, [credentials?.validateCode, prevValidateCode]);
    98
    99      useEffect(() => {
   100          if (!input2FARef.current || !!prevRequiresTwoFactorAuth || !account?.requiresTwoFactorAuth) {
   101              return;
   102          }
   103          input2FARef.current.focus();
   104      }, [account?.requiresTwoFactorAuth, prevRequiresTwoFactorAuth]);
   105
   106      useEffect(() => {
   107          if (!inputValidateCodeRef.current || validateCode.length > 0) {
   108              return;
   109          }
   110          inputValidateCodeRef.current.clear();
   111      }, [validateCode]);
   112
   113      useEffect(() => {
   114          if (!input2FARef.current || twoFactorAuthCode.length > 0) {
   115              return;
   116          }
   117          input2FARef.current.clear();
   118      }, [twoFactorAuthCode]);
   119
   120      useEffect(() => {
   121          if (timeRemaining > 0) {
   122              timerRef.current = setTimeout(() => {
   123                  setTimeRemaining(timeRemaining - 1);
   124              }, 1000);
   125          }
   126          return () => {
   127              clearTimeout(timerRef.current);
   128          };
   129      }, [timeRemaining]);
   130
   131      /**
   132       * Handle text input and clear formError upon text change
   133       */
   134      const onTextInput = (text: string, key: ValidateCodeFormVariant) => {
   135          if (key === 'validateCode') {
   136              setValidateCode(text);
   137          }
   138          if (key === 'twoFactorAuthCode') {
   139              setTwoFactorAuthCode(text);
   140          }
   141          if (key === 'recoveryCode') {
   142              setRecoveryCode(text.trim());
   143          }
   144
   145          setFormError((prevError) => ({...prevError, [key]: undefined}));
   146
   147          if (account?.errors) {
   148              SessionActions.clearAccountMessages();
   149          }
   150      };
   151
   152      /**
   153       * Trigger the reset validate code flow and ensure the 2FA input field is reset to avoid it being permanently hidden
   154       */
   155      const resendValidateCode = () => {
   156          User.resendValidateCode(credentials?.login ?? '');
   157          inputValidateCodeRef.current?.clear();
   158          // Give feedback to the user to let them know the email was sent so that they don't spam the button.
   159          setTimeRemaining(CONST.REQUEST_CODE_DELAY);
   160      };
   161
   162      /**
   163       * Clear local sign in states
   164       */
   165      const clearLocalSignInData = useCallback(() => {
   166          setTwoFactorAuthCode('');
   167          setFormError({});
   168          setValidateCode('');
   169          setIsUsingRecoveryCode(false);
   170          setRecoveryCode('');
   171      }, [setIsUsingRecoveryCode]);
   172
   173      /**
   174       * Clears local and Onyx sign in states
   175       */
   176      const clearSignInData = useCallback(() => {
   177          clearLocalSignInData();
   178          SessionActions.clearSignInData();
   179      }, [clearLocalSignInData]);
   180
   181      useImperativeHandle(forwardedRef, () => ({
   182          clearSignInData,
   183      }));
   184
   185      useEffect(() => {
   186          if (!needToClearError) {
   187              return;
   188          }
   189
   190          if (account?.errors) {
   191              SessionActions.clearAccountMessages();
   192              return;
   193          }
   194          setNeedToClearError(false);
   195      }, [account?.errors, needToClearError]);
   196
   197      /**
   198       * Switches between 2fa and recovery code, clears inputs and errors
   199       */
   200      const switchBetween2faAndRecoveryCode = () => {
   201          setIsUsingRecoveryCode(!isUsingRecoveryCode);
   202
   203          setRecoveryCode('');
   204          setTwoFactorAuthCode('');
   205
   206          setFormError((prevError) => ({...prevError, recoveryCode: undefined, twoFactorAuthCode: undefined}));
   207
   208          if (account?.errors) {
   209              SessionActions.clearAccountMessages();
   210          }
   211      };
   212
   213      useEffect(() => {
   214          if (!isLoadingResendValidationForm) {
   215              return;
   216          }
   217          clearLocalSignInData();
   218          // `clearLocalSignInData` is not required as a dependency, and adding it
   219          // overcomplicates things requiring clearLocalSignInData function to use useCallback
   220          // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   221      }, [isLoadingResendValidationForm]);
   222
   223      useEffect(() => {
   224          if (!hasError) {
   225              return;
   226          }
   227
   228          setFormError({});
   229      }, [hasError]);
   230
   231      /**
   232       * Check that all the form fields are valid, then trigger the submit callback
   233       */
   234      const validateAndSubmitForm = useCallback(() => {
   235          if (account?.isLoading) {
   236              return;
   237          }
   238          if (account?.errors) {
   239              SessionActions.clearAccountMessages();
   240          }
   241          const requiresTwoFactorAuth = account?.requiresTwoFactorAuth;
   242          if (requiresTwoFactorAuth) {
   243              if (input2FARef.current) {
   244                  input2FARef.current.blur();
   245              }
   246              /**
   247               * User could be using either recovery code or 2fa code
   248               */
   249              if (!isUsingRecoveryCode) {
   250                  if (!twoFactorAuthCode.trim()) {
   251                      setFormError({twoFactorAuthCode: 'validateCodeForm.error.pleaseFillTwoFactorAuth'});
   252                      return;
   253                  }
   254                  if (!ValidationUtils.isValidTwoFactorCode(twoFactorAuthCode)) {
   255                      setFormError({twoFactorAuthCode: 'passwordForm.error.incorrect2fa'});
   256                      return;
   257                  }
   258              } else {
   259                  if (!recoveryCode.trim()) {
   260                      setFormError({recoveryCode: 'recoveryCodeForm.error.pleaseFillRecoveryCode'});
   261                      return;
   262                  }
   263                  if (!ValidationUtils.isValidRecoveryCode(recoveryCode)) {
   264                      setFormError({recoveryCode: 'recoveryCodeForm.error.incorrectRecoveryCode'});
   265                      return;
   266                  }
   267              }
   268          } else {
   269              if (inputValidateCodeRef.current) {
   270                  inputValidateCodeRef.current.blur();
   271              }
   272              if (!validateCode.trim()) {
   273                  setFormError({validateCode: 'validateCodeForm.error.pleaseFillMagicCode'});
   274                  return;
   275              }
   276              if (!ValidationUtils.isValidValidateCode(validateCode)) {
   277                  setFormError({validateCode: 'validateCodeForm.error.incorrectMagicCode'});
   278                  return;
   279              }
   280          }
   281          setFormError({});
   282
   283          const recoveryCodeOr2faCode = isUsingRecoveryCode ? recoveryCode : twoFactorAuthCode;
   284
   285          const accountID = credentials?.accountID;
   286          if (accountID) {
   287              SessionActions.signInWithValidateCode(accountID, validateCode, recoveryCodeOr2faCode);
   288          } else {
   289              SessionActions.signIn(validateCode, recoveryCodeOr2faCode);
   290          }
   291      }, [account, credentials, twoFactorAuthCode, validateCode, isUsingRecoveryCode, recoveryCode]);
   292
   293      return (
   294          <SafariFormWrapper>
   295              {/* At this point, if we know the account requires 2FA we already successfully authenticated */}
   296              {account?.requiresTwoFactorAuth ? (
   297                  <View style={[styles.mv3]}>
   298                      {isUsingRecoveryCode ? (
   299                          <TextInput
   300                              shouldDelayFocus
   301                              accessibilityLabel={translate('recoveryCodeForm.recoveryCode')}
   302                              value={recoveryCode}
   303                              onChangeText={(text) => onTextInput(text, 'recoveryCode')}
   304                              maxLength={CONST.FORM_CHARACTER_LIMIT}
   305                              label={translate('recoveryCodeForm.recoveryCode')}
   306                              errorText={formError?.recoveryCode ? translate(formError?.recoveryCode) : ''}
   307                              hasError={hasError}
   308                              autoFocus
   309                          />
   310                      ) : (
   311                          <MagicCodeInput
   312                              shouldDelayFocus
   313                              autoComplete={autoComplete}
   314                              ref={(magicCodeInput) => {
   315                                  if (!magicCodeInput) {
   316                                      return;
   317                                  }
   318                                  input2FARef.current = magicCodeInput;
   319                              }}
   320                              name="twoFactorAuthCode"
   321                              value={twoFactorAuthCode}
   322                              onChangeText={(text) => onTextInput(text, 'twoFactorAuthCode')}
   323                              onFulfill={validateAndSubmitForm}
   324                              maxLength={CONST.TFA_CODE_LENGTH}
   325                              errorText={formError?.twoFactorAuthCode ? translate(formError?.twoFactorAuthCode) : ''}
   326                              hasError={hasError}
   327                              autoFocus
   328                              key="twoFactorAuthCode"
   329                          />
   330                      )}
   331                      {hasError && <FormHelpMessage message={ErrorUtils.getLatestErrorMessage(account)} />}
   332                      <PressableWithFeedback
   333                          key={isUsingRecoveryCode.toString()}
   334                          style={[styles.mt2]}
   335                          onPress={switchBetween2faAndRecoveryCode}
   336                          hoverDimmingValue={1}
   337                          disabled={isValidateCodeFormSubmitting}
   338                          role={CONST.ROLE.BUTTON}
   339                          accessibilityLabel={isUsingRecoveryCode ? translate('recoveryCodeForm.use2fa') : translate('recoveryCodeForm.useRecoveryCode')}
   340                      >
   341                          <Text style={[styles.link]}>{isUsingRecoveryCode ? translate('recoveryCodeForm.use2fa') : translate('recoveryCodeForm.useRecoveryCode')}</Text>
   342                      </PressableWithFeedback>
   343                  </View>
   344              ) : (
   345                  <View style={[styles.mv3]}>
   346                      <MagicCodeInput
   347                          autoComplete={autoComplete}
   348                          ref={(magicCodeInput) => {
   349                              if (!magicCodeInput) {
   350                                  return;
   351                              }
   352                              inputValidateCodeRef.current = magicCodeInput;
   353                          }}
   354                          name="validateCode"
   355                          value={validateCode}
   356                          onChangeText={(text) => onTextInput(text, 'validateCode')}
   357                          onFulfill={validateAndSubmitForm}
   358                          errorText={formError?.validateCode ? translate(formError?.validateCode) : ''}
   359                          hasError={hasError}
   360                          autoFocus
   361                          key="validateCode"
   362                          testID="validateCode"
   363                      />
   364                      {hasError && <FormHelpMessage message={ErrorUtils.getLatestErrorMessage(account)} />}
   365                      <View style={[styles.alignItemsStart]}>
   366                          {timeRemaining > 0 && !isOffline ? (
   367                              <Text style={[styles.mt2]}>
   368                                  {translate('validateCodeForm.requestNewCode')}
   369                                  <Text style={[styles.textBlue]}>00:{String(timeRemaining).padStart(2, '0')}</Text>
   370                              </Text>
   371                          ) : (
   372                              <PressableWithFeedback
   373                                  style={[styles.mt2]}
   374                                  onPress={resendValidateCode}
   375                                  disabled={shouldDisableResendValidateCode}
   376                                  hoverDimmingValue={1}
   377                                  pressDimmingValue={0.2}
   378                                  role={CONST.ROLE.BUTTON}
   379                                  accessibilityLabel={translate('validateCodeForm.magicCodeNotReceived')}
   380                              >
   381                                  <Text style={[StyleUtils.getDisabledLinkStyles(shouldDisableResendValidateCode)]}>
   382                                      {hasError ? translate('validateCodeForm.requestNewCodeAfterErrorOccurred') : translate('validateCodeForm.magicCodeNotReceived')}
   383                                  </Text>
   384                              </PressableWithFeedback>
   385                          )}
   386                      </View>
   387                  </View>
   388              )}
   389              <View>
   390                  <Button
   391                      isDisabled={isOffline}
   392                      success
   393                      large
   394                      style={[styles.mv3]}
   395                      text={translate('common.signIn')}
   396                      isLoading={isValidateCodeFormSubmitting}
   397                      onPress={validateAndSubmitForm}
   398                  />
   399                  <ChangeExpensifyLoginLink onPress={clearSignInData} />
   400              </View>
   401              <View style={[styles.mt5, styles.signInPageWelcomeTextContainer]}>
   402                  <Terms />
   403              </View>
   404          </SafariFormWrapper>
   405      );
   406  }
